START TRANSACTION;
CREATE TABLE home_comment_action_mutations(request_key VARCHAR(191) NOT NULL,operation_id BIGINT UNSIGNED NOT NULL UNIQUE,player_id BIGINT UNSIGNED NOT NULL,action_kind ENUM('guide','write','read') NOT NULL,comment_id BIGINT UNSIGNED NULL,result_json LONGTEXT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),PRIMARY KEY(request_key),CONSTRAINT fk_home_comment_action_operation FOREIGN KEY(operation_id) REFERENCES operations(id),CONSTRAINT fk_home_comment_action_player FOREIGN KEY(player_id) REFERENCES players(id),CONSTRAINT fk_home_comment_action_comment FOREIGN KEY(comment_id) REFERENCES home_comments(id),CONSTRAINT chk_home_comment_action_result CHECK(JSON_VALID(result_json))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO command_registry(command_code,handler_key,auth_scope,rollout_state,enabled,version) VALUES('HOME_COMMENT_ACTION','home_comment_action','VERIFIED_USER','SHADOW',TRUE,1) ON DUPLICATE KEY UPDATE handler_key=VALUES(handler_key),auth_scope=VALUES(auth_scope),rollout_state=VALUES(rollout_state),enabled=TRUE,version=version+1;
INSERT INTO command_aliases(command_text,command_code,active) VALUES('/댓글','HOME_COMMENT_ACTION',TRUE),('/댓글확인','HOME_COMMENT_ACTION',TRUE) ON DUPLICATE KEY UPDATE command_code=VALUES(command_code),active=TRUE;
COMMIT;
